// This file is generated by AI.

// 文档警告块 (GFM Alert) 渲染的测试。
//
// 这里用 `new Marked()` 的独立实例验证扩展本身的行为 (与 Monaco 内部实例共用同一套 marked
// 扩展 API, 见 doc-alert.ts): 文档里 `> [!WARNING]` 这类写法要变成带类型与标题的警告块,
// 块内的 Markdown (行内代码 / 多段 / 代码块) 照常渲染, 普通引用块不受影响。
//
// 断言用的是**消毒器放行的那份标记** (`<div data-alert="…">`): Monaco 只放行 span 上的
// class, 其余元素的 class 会被剥掉, 所以扩展产出的类名会被换成 data 属性 —— 这里顺势把
// 「最终 DOM 长什么样」钉住, 免得哪天改回类名后样式在界面上静默失效。

import { Marked } from 'marked';
import { describe, expect, it } from 'vitest';

import { installDocAlerts } from './doc-alert';

/** 用注册过警告块扩展的独立 marked 实例渲染一段文档。 */
function render(markdown: string): string {
  const marked = new Marked();
  installDocAlerts(marked);
  return marked.parse(markdown, { async: false }) as string;
}

describe('文档警告块', () => {
  it('把 [!WARNING] 渲染成警告块, 并去掉标记本身', () => {
    const html = render('> [!WARNING]\n> 参数名不要使用 `when`。');

    expect(html).toContain('<div data-alert="warning">');
    expect(html).toContain('<p>警告</p>');
    expect(html).toContain('参数名不要使用 <code>when</code>。');
    expect(html).not.toContain('[!WARNING]');
    // 类名会被 Monaco 的消毒器剥掉, 不该留在标记里
    expect(html).not.toContain('markdown-alert');
  });

  it('五种类型各自成块, 标题与类型一一对应', () => {
    const variants = [
      ['NOTE', 'note', '注意'],
      ['TIP', 'tip', '提示'],
      ['IMPORTANT', 'important', '重要'],
      ['WARNING', 'warning', '警告'],
      ['CAUTION', 'caution', '小心'],
    ];

    for (const [marker, type, title] of variants) {
      const html = render(`> [!${marker}]\n> 内容`);

      expect(html).toContain(`<div data-alert="${type}">`);
      expect(html).toContain(`<p>${title}</p>`);
    }
  });

  it('警告块里的多段与代码块照常渲染', () => {
    const html = render('> [!TIP]\n> 示例:\n>\n> 第一段\n>\n> ```webgal\n> wait:456;\n> ```');

    expect(html).toContain('<div data-alert="tip">');
    expect(html).toContain('<p>示例:</p>');
    expect(html).toContain('<p>第一段</p>');
    // 代码块交给 Monaco 的代码块渲染器 (这里只看 marked 产出的语言类名)
    expect(html).toContain('<pre><code class="language-webgal">wait:456;');
  });

  it('普通引用块不受影响', () => {
    const html = render('> **实验性功能**：配音工作流还在逐步完善中。');

    expect(html).toContain('<blockquote>');
    expect(html).toContain('<strong>实验性功能</strong>');
    expect(html).not.toContain('data-alert');
  });
});
